39	+import { z } from "zod";
40	+import { KIT_IDS, type KitId } from "../moves/index.js";
41	+import { formatIssues, type ValidationResult } from "../rules.js";
42	+
43	+/** What a player may read about a kit before committing to it (§9's kit table). */
44	+export interface KitDescription {
45	+  readonly kit: KitId;
46	+  readonly name: string;
47	+  /** The two signature specials, U then I. */
48	+  readonly specials: readonly [string, string];
49	+  readonly advantage: string;
50	+  readonly vulnerability: string;
51	+}
52	+
53	+const text = z.string().min(1).max(120);
54	+
55	+export const kitDescriptionSchema = z.strictObject({
56	+  kit: z.enum(KIT_IDS),
57	+  name: text,
58	+  specials: z.tuple([text, text]),
59	+  advantage: text,
60	+  vulnerability: text,
61	+});
62	+
63	+/** §9's table, one entry per kit of `KIT_IDS`. */
64	+export const kitDescriptions: Readonly<Record<KitId, KitDescription>> = {
65	+  duelist: {
66	+    kit: "duelist",
67	+    name: "Duelist",
68	+    specials: ["Advancing thrust", "Counter slash"],
69	+    advantage: "Reliable close combat and meter use",
70	+    vulnerability: "Limited long-range pressure",
71	+  },
72	+  ember: {
73	+    kit: "ember",
74	+    name: "Ember",
75	+    specials: ["Flame bolt", "Rising flare"],
76	+    advantage: "Controls space and punishes jumps",
77	+    vulnerability: "Long recovery if attacks miss",
78	+  },
79	+  smoke: {
80	+    kit: "smoke",
81	+    name: "Smoke",
82	+    specials: ["Short feint dash", "Smoke screen"],
83	+    advantage: "Changes spacing and obscures intent",
84	+    vulnerability: "Low direct damage; readable reappearance",
85	+  },
86	+};
87	+
88	+/** Checks every description against the schema and that each one sits under its own kit id. */
89	+export function validateKitDescriptions(candidate: unknown): ValidationResult<Record<KitId, KitDescription>> {
90	+  const parsed = z.record(z.enum(KIT_IDS), kitDescriptionSchema).safeParse(candidate);
91	+  if (!parsed.success) return { ok: false, issues: formatIssues(parsed.error) };
92	+  const issues = KIT_IDS.flatMap((kit) => {
93	+    const entry = parsed.data[kit];
94	+    if (entry === undefined) return [`${kit}: missing`];
95	+    return entry.kit === kit ? [] : [`${kit}.kit: must be ${kit}, got ${entry.kit}`];
96	+  });
97	+  return issues.length === 0 ? { ok: true, value: parsed.data as Record<KitId, KitDescription> } : { ok: false, issues };
98	+}
