141	+    expect(Object.keys(kitDescriptions).sort()).toEqual([...KIT_IDS].sort());
142	+    expect(validateKitDescriptions(kitDescriptions)).toEqual({ ok: true, value: kitDescriptions });
143	+    expect(kitDescriptions.ember.specials).toEqual(["Flame bolt", "Rising flare"]);
144	+    expect(kitDescriptions.smoke.vulnerability).toMatch(/readable reappearance/);
145	+  });
146	+
147	+  it("refuse a missing kit, a description under another id and an empty text", () => {
148	+    const { smoke: _, ...missing } = kitDescriptions;
149	+    expect(validateKitDescriptions(missing).ok).toBe(false);
150	+    expect(validateKitDescriptions({ ...kitDescriptions, smoke: { ...kitDescriptions.ember } })).toEqual({ ok: false, issues: ["smoke.kit: must be smoke, got ember"] });
151	+    expect(validateKitDescriptions({ ...kitDescriptions, ember: { ...kitDescriptions.ember, advantage: "" } }).ok).toBe(false);
152	+  });
