168	+import { z } from "zod";
169	+import { KIT_IDS, type KitId } from "../moves/index.js";
170	+import { formatIssues, type ValidationResult } from "../rules.js";
171	+import { WORLD_STEPS_PER_SECOND } from "../sailing.js";
172	+
173	+/** §9: eating a fruit takes three seconds of held interact, and can be interrupted. */
174	+export const FRUIT_EAT_SECONDS = 3;
175	+/** §9: "two of each type". Each pedestal holds one fruit, feeds one player once, and never refills. */
176	+export const PEDESTALS_PER_FRUIT_KIT = 2;
177	+
178	+/** The kits a pedestal can hold: every kit but the Duelist, which every player starts with (§9). */
179	+export type FruitKitId = Exclude<KitId, "duelist">;
180	+export const FRUIT_KIT_IDS: readonly FruitKitId[] = KIT_IDS.filter((kit): kit is FruitKitId => kit !== "duelist");
181	+
182	+/** The fruit rules (§9) in world ticks (20 a second). */
183	+export const fruitRulesSchema = z.strictObject({
184	+  /** World ticks of held interact that eat a fruit; the last of them eats it. */
185	+  eatTicks: z.int().positive(),
186	+  /** Pedestals dealt for each fruit kit. */
187	+  pedestalsPerKit: z.int().positive(),
188	+});
189	+
190	+export type FruitRules = z.infer<typeof fruitRulesSchema>;
191	+
192	+export const fruitRules: FruitRules = {
193	+  eatTicks: FRUIT_EAT_SECONDS * WORLD_STEPS_PER_SECOND,
194	+  pedestalsPerKit: PEDESTALS_PER_FRUIT_KIT,
195	+};
196	+
197	+export function validateFruitRules(candidate: unknown): ValidationResult<FruitRules> {
198	+  const parsed = fruitRulesSchema.safeParse(candidate);
199	+  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
200	+}
