222	@@ -0,0 +1,290 @@
223	+import { rulesPresets } from "@pirate-sea-race/content";
224	+import { describe, expect, it } from "vitest";
225	+import {
226	+  checkFruitState,
227	+  createFruitConfig,
228	+  createFruitState,
229	+  fruitRules,
230	+  hashState,
231	+  inspectPedestal,
232	+  kitDescriptions,
233	+  kitOf,
234	+  stepFruits,
235	+  type FruitPlayer,
236	+  type FruitResult,
237	+  type FruitSite,
238	+  type FruitState,
239	+} from "./index.js";
240	+
241	+const config = createFruitConfig();
242	+const EAT = config.eatTicks;
243	+const SITES: FruitSite[] = [
244	+  { id: "north", x: 1000, y: 200 },
245	+  { id: "east", x: 2000, y: 1000 },
246	+  { id: "south", x: 1000, y: 2000 },
247	+  { id: "west", x: 200, y: 1000 },
248	+];
249	+const SEED = 0x5eed;
250	+const fresh = () => createFruitState(SITES, SEED, rulesPresets.slice);
251	+
252	+/** A player holding interact at a pedestal, connected, free and present. */
253	+function at(playerId: string, pedestalId: string | null, change: Partial<FruitPlayer> = {}): FruitPlayer {
254	+  return { playerId, pedestalId, holding: true, reserved: false, disconnected: false, left: false, ...change };
255	+}
256	+
257	+/** Recursively frozen, so a step that mutated its input would throw. */
258	+function deepFreeze<T>(value: T): T {
259	+  if (typeof value === "object" && value !== null && !Object.isFrozen(value)) {
260	+    Object.freeze(value);
261	+    for (const child of Object.values(value)) deepFreeze(child);
262	+  }
263	+  return value;
264	+}
265	+
266	+/** Steps the next tick with frozen input and state, checking neither changes and the invariants hold. */
267	+function step(state: FruitState, players: FruitPlayer[], tick = state.tick + 1) {
268	+  const before = hashState(deepFreeze(state));
269	+  const stepped = stepFruits(config, state, deepFreeze({ tick, players }));
270	+  expect(hashState(state)).toBe(before);
271	+  expect(checkFruitState(stepped.state)).toEqual([]);
272	+  return stepped;
273	+}
274	+
275	+/** Steps `count` identical ticks, returning the final state and every result. */
276	+function hold(state: FruitState, players: FruitPlayer[], count: number) {
277	+  const results: FruitResult[] = [];
278	+  let current = state;
279	+  for (let index = 0; index < count; index++) {
280	+    const stepped = step(current, players);
281	+    current = stepped.state;
282	+    results.push(...stepped.results);
283	+  }
284	+  return { state: current, results };
285	+}
286	+
287	+const completions = (results: readonly FruitResult[]) => results.filter((result) => result.kind === "eat-completed");
288	+
289	+describe("dealing (§9)", () => {
290	+  it("deals two of each fruit kit onto the sites, the same way for the same seed and sites", () => {
291	+    const state = fresh();
292	+    expect(state.tick).toBe(0);
293	+    expect(state.channels).toEqual([]);
294	+    expect(state.meals).toEqual([]);
295	+    expect(state.pedestals.map((pedestal) => pedestal.id)).toEqual(SITES.map((site) => site.id));
296	+    expect(state.pedestals.map((pedestal) => pedestal.kit).sort()).toEqual(["ember", "ember", "smoke", "smoke"]);
297	+    expect(state.pedestals.every((pedestal) => pedestal.eatenBy === null)).toBe(true);
298	+    expect(hashState(fresh())).toBe(hashState(state));
299	+    expect(checkFruitState(state)).toEqual([]);
300	+  });
301	+
302	+  it("deals differently across seeds, and every deal is a permutation of the deck", () => {
303	+    const deals = new Set<string>();
304	+    for (let seed = 0; seed < 200; seed++) {
305	+      const kits = createFruitState(SITES, seed, rulesPresets.slice).pedestals.map((pedestal) => pedestal.kit);
306	+      expect([...kits].sort()).toEqual(["ember", "ember", "smoke", "smoke"]);
307	+      deals.add(kits.join());
308	+    }
309	+    // All six arrangements of two Ember and two Smoke appear.
310	+    expect(deals.size).toBe(6);
311	+  });
312	+
313	+  it("refuses too few or too many sites, duplicate ids and fractional positions", () => {
314	+    expect(() => createFruitState(SITES.slice(0, 3), SEED, rulesPresets.slice)).toThrow(/needs 4 pedestal sites .* got 3/);
315	+    expect(() => createFruitState([...SITES, { id: "hub", x: 0, y: 0 }], SEED, rulesPresets.slice)).toThrow(/needs 4 pedestal sites .* got 5/);
316	+    expect(() => createFruitState([...SITES.slice(0, 3), { ...SITES[0]! }], SEED, rulesPresets.slice)).toThrow(/appears twice/);
317	+    expect(() => createFruitState([...SITES.slice(0, 3), { id: "", x: 0, y: 0 }], SEED, rulesPresets.slice)).toThrow(/non-empty/);
318	+    expect(() => createFruitState([...SITES.slice(0, 3), { id: "w", x: 0.5, y: 0 }], SEED, rulesPresets.slice)).toThrow(/safe integer/);
319	+    expect(() => createFruitState(SITES, 1.5, rulesPresets.slice)).toThrow(/seed/);
320	+  });
321	+
322	+  it("refuses the alpha preset until its six fruit kits exist", () => {
323	+    const alphaSites = Array.from({ length: 12 }, (_, index) => ({ id: `p${index}`, x: index, y: 0 }));
324	+    expect(() => createFruitState(alphaSites, SEED, rulesPresets.alpha)).toThrow("the alpha preset deals 6 fruit kits, but only 2 exist (ember, smoke)");
325	+    expect(() => createFruitState(SITES, SEED, rulesPresets.alpha)).toThrow(/deals 6 fruit kits/);
326	+  });
327	+
328	+  it("refuses invalid fruit rules and follows valid ones", () => {
329	+    expect(() => createFruitConfig({ ...fruitRules, eatTicks: 0 })).toThrow(/invalid fruit rules/);
330	+    const six = Array.from({ length: 6 }, (_, index) => ({ id: `p${index}`, x: index, y: 0 }));
331	+    const state = createFruitState(six, SEED, rulesPresets.slice, { rules: { ...fruitRules, pedestalsPerKit: 3 }, tick: 40 });
332	+    expect(state.pedestals).toHaveLength(6);
333	+    expect(state.tick).toBe(40);
334	+  });
335	+});
336	+
337	+describe("eating (§9)", () => {
338	+  it("eats after 60 held ticks, not 59", () => {
339	+    expect(EAT).toBe(60);
340	+    const almost = hold(fresh(), [at("a", "north")], EAT - 1);
341	+    expect(almost.results[0]).toEqual({ kind: "eat-started", tick: 1, playerId: "a", pedestalId: "north" });
342	+    expect(completions(almost.results)).toEqual([]);
343	+    expect(almost.state.channels).toEqual([{ playerId: "a", pedestalId: "north", startTick: 1, lastTick: EAT - 1, held: EAT - 1 }]);
344	+    expect(kitOf(almost.state, "a")).toBe("duelist");
345	+
346	+    const eaten = step(almost.state, [at("a", "north")]);
347	+    const kit = fresh().pedestals[0]!.kit;
348	+    expect(eaten.results).toEqual([{ kind: "eat-completed", tick: EAT, playerId: "a", pedestalId: "north", kit }]);
349	+    expect(eaten.state.channels).toEqual([]);
350	+    expect(eaten.state.meals).toEqual([{ playerId: "a", pedestalId: "north", kit, tick: EAT }]);
351	+    expect(eaten.state.pedestals[0]!.eatenBy).toBe("a");
352	+    expect(kitOf(eaten.state, "a")).toBe(kit);
353	+  });
354	+
355	+  it("resets on a released tick, and on an absent one", () => {
356	+    for (const gapTick of [at("a", "north", { holding: false }), at("a", null)]) {
357	+      const first = hold(fresh(), [at("a", "north")], EAT - 1);
358	+      const gap = step(first.state, [gapTick]);
359	+      expect(gap.results).toEqual([{ kind: "eat-interrupted", tick: EAT, playerId: "a", pedestalId: "north", reason: "released", held: EAT - 1 }]);
360	+      const again = hold(gap.state, [at("a", "north")], EAT - 1);
361	+      expect(completions(again.results)).toEqual([]);
362	+      expect(completions(step(again.state, [at("a", "north")]).results)).toHaveLength(1);
363	+    }
364	+    const absent = step(hold(fresh(), [at("a", "north")], 5).state, []);
365	+    expect(absent.results).toEqual([{ kind: "eat-interrupted", tick: 6, playerId: "a", pedestalId: "north", reason: "released", held: 5 }]);
366	+  });
367	+
368	+  it("resets on a skipped world tick", () => {
369	+    const first = hold(fresh(), [at("a", "north")], 10);
370	+    const skipped = step(first.state, [at("a", "north")], 12);
371	+    expect(skipped.results).toEqual([
372	+      { kind: "eat-interrupted", tick: 12, playerId: "a", pedestalId: "north", reason: "gap", held: 10 },
373	+      { kind: "eat-started", tick: 12, playerId: "a", pedestalId: "north" },
374	+    ]);
375	+    expect(skipped.state.channels[0]).toMatchObject({ startTick: 12, held: 1 });
376	+  });
377	+
378	+  it.each(["reserved", "disconnected", "left"] as const)("resets when the player is %s, and refuses while it lasts", (flag) => {
379	+    const first = hold(fresh(), [at("a", "north")], 30);
380	+    const broken = step(first.state, [at("a", "north", { [flag]: true })]);
381	+    expect(broken.results).toEqual([{ kind: "eat-interrupted", tick: 31, playerId: "a", pedestalId: "north", reason: flag, held: 30 }]);
382	+    const still = step(broken.state, [at("a", "north", { [flag]: true })]);
383	+    expect(still.results).toEqual([{ kind: "eat-refused", tick: 32, playerId: "a", pedestalId: "north", reason: flag }]);
384	+    expect(still.state.channels).toEqual([]);
385	+    const resumed = hold(still.state, [at("a", "north")], EAT);
386	+    expect(resumed.results[0]).toMatchObject({ kind: "eat-started", tick: 33 });
387	+    expect(completions(resumed.results)).toEqual([expect.objectContaining({ tick: 32 + EAT })]);
388	+  });
389	+
