629	+    if (input.tick <= state.tick) expect(stepped.state).toBe(state);
630	+    state = stepped.state;
631	+    states.push(state);
632	+    results.push([...stepped.results]);
633	+  }
634	+  return { states, hashes: states.map(hashState), results };
635	+}
