747	+export interface FruitSite {
748	+  /** The pedestal's stable id, as the caller names it in each tick's facts. */
749	+  readonly id: string;
750	+  /** Position in sub-units, for the caller's own use. */
751	+  readonly x: number;
752	+  readonly y: number;
753	+}
