780	+  readonly kit: FruitKitId;
781	+  readonly tick: number;
782	+}
783	+
784	+/** The fruit state: plain integer data that `hashState` covers entirely. */
785	+export interface FruitState {
786	+  /** The last world tick processed. */
787	+  readonly tick: number;
788	+  /** In site order. */
789	+  readonly pedestals: readonly FruitPedestal[];
790	+  /** Sorted by player id. */
791	+  readonly channels: readonly FruitChannel[];
792	+  /** Sorted by player id; a player appears at most once and is never removed. */
793	+  readonly meals: readonly FruitMeal[];
