1	/**
2	 * Canonical serialization: object keys sorted, integers only for numbers, no undefined. Two equal states always
3	 * serialize to the same string, whatever order their keys were written in.
4	 */
5	export function canonicalize(value: unknown): string {
6	  if (value === null) return "null";
7	  switch (typeof value) {
8	    case "number":
9	      if (!Number.isSafeInteger(value)) throw new TypeError(`state numbers must be safe integers, got ${value}`);
10	      return String(value);
11	    case "string":
12	      return JSON.stringify(value);
