17	  findSource,
18	  heldTypes,
19	  type LedgerChannel,
20	  type LedgerState,
21	} from "./state.js";
22	
23	/**
24	 * - `started`: a new channel, at 0 held ticks.
25	 * - `held`: one more tick held.
26	 * - `reset`: the hold was interrupted (a tick without progress), so it counts from 0 again at this tick.
27	 * - `collected` / `claimed`: the channel completed and the rubbing is the player's.
28	 * - `failed`: the channel completed but its rubbing had gone or was no longer allowed (see `failure`); nothing moved.
29	 * - `cancelled`: the channel was dropped.
30	 */
31	export type ChannelStatus = "started" | "held" | "reset" | "collected" | "claimed" | "failed" | "cancelled";
32	
33	export interface ChannelResult {
34	  readonly ok: boolean;
35	  readonly rejection: LedgerRejection | null;
36	  readonly status: ChannelStatus | null;
37	  /** Why a completed channel failed. */
38	  readonly failure: LedgerRejection | null;
39	  /** The player's channel as it now stands. */
40	  readonly channel: LedgerChannel | null;
41	  /** The rubbing collected or claimed. */
42	  readonly rubbingId: string | null;
43	  readonly transfers: readonly Transfer[];
44	}
45	
46	function rejected(state: LedgerState, rejection: LedgerRejection, playerId: unknown): LedgerStep<ChannelResult> {
47	  const channel = typeof playerId === "string" ? (findPlayer(state, playerId)?.channel ?? null) : null;
48	  return { state, result: { ok: false, rejection, status: null, failure: null, channel, rubbingId: null, transfers: [] } };
49	}
50	
51	function result(
52	  state: LedgerState,
53	  playerId: string,
54	  status: ChannelStatus,
55	  extra: { failure?: LedgerRejection; rubbingId?: string; transfers?: Transfer[] } = {},
56	): LedgerStep<ChannelResult> {
57	  return {
58	    state,
59	    result: {
60	      ok: true,
61	      rejection: null,
62	      status,
63	      failure: extra.failure ?? null,
64	      channel: findPlayer(state, playerId)?.channel ?? null,
65	      rubbingId: extra.rubbingId ?? null,
66	      transfers: extra.transfers ?? [],
67	    },
68	  };
69	}
70	
71	/** Why a player cannot start or keep a channel: they must be in the match, connected and out of any duel. */
72	function actorRejection(state: LedgerState, playerId: unknown): LedgerRejection | null {
73	  const refusal = playerRejection(state, playerId);
74	  if (refusal) return refusal;
75	  const id = playerId as string;
76	  if (findPlayer(state, id)!.status === "disconnected") return "player-disconnected";
77	  return activeDuelOf(state, id) ? "player-in-duel" : null;
