1	/**
2	 * The last step of `npm run build`: proves the build output runs, not just that it compiled. It loads every workspace
3	 * package through its `default` export (the built `dist/`), checks that the web bundle carries no development-only
4	 * latency setting, starts the built server (`node apps/server/dist/main.js`) on a free port, waits for its health
5	 * check, creates a private match through the Colyseus SDK and waits for the creator's ship, checks that the production
6	 * entry offers no test-only placement route, and opens a practice duel whose client runs the built rollback core
7	 * through the countdown into the fight. Every wait is bounded and the server is killed on every path, so a failure
8	 * fails the build with its real error and no process outlives the script.
9	 */
10	import { spawn, type ChildProcess } from "node:child_process";
11	import { readdir, readFile } from "node:fs/promises";
12	import { createInterface } from "node:readline";
13	import { fileURLToPath } from "node:url";
14	
15	const root = fileURLToPath(new URL("..", import.meta.url));
16	const SERVER_ENTRY = "apps/server/dist/main.js";
17	const LISTENING_LINE = /listening on ws:\/\/localhost:(\d+)/;
18	
19	const LISTEN_TIMEOUT_MS = 20_000;
20	const HEALTH_TIMEOUT_MS = 10_000;
21	const MATCH_TIMEOUT_MS = 15_000;
22	/** A practice duel's three-second countdown and its first confirmed frames. */
23	const DUEL_TIMEOUT_MS = 15_000;
24	/** The web build's assets, and the marker the development-only latency module logs (apps/web/src/devLatency.ts). */
25	const WEB_ASSETS = "apps/web/dist/assets";
26	const DEV_LATENCY_MARKER = "pirate-sea-race dev latency";
27	const STOP_TIMEOUT_MS = 5_000;
28	/** Everything together stays far below the build check's 600 s. */
29	const OVERALL_TIMEOUT_MS = 90_000;
30	
31	/** The built entry points, as a consumer without the `@pirate-sea-race/source` condition resolves them. */
32	const WORKSPACE_EXPORTS = [
33	  "@pirate-sea-race/content",
34	  "@pirate-sea-race/content/moves",
35	  "@pirate-sea-race/content/ruins",
36	  "@pirate-sea-race/content/encounters",
37	  "@pirate-sea-race/content/intel",
38	  "@pirate-sea-race/content/match",
39	  "@pirate-sea-race/content/claim",
40	  "@pirate-sea-race/content/objectives",
41	  "@pirate-sea-race/protocol",
42	  "@pirate-sea-race/simulation",
43	  "@pirate-sea-race/simulation/duel",
44	  "@pirate-sea-race/simulation/claim",
45	  "@pirate-sea-race/simulation/objectives",
46	  "@pirate-sea-race/simulation/netcode",
47	  "@pirate-sea-race/simulation/ruins",
48	  "@pirate-sea-race/simulation/encounters",
49	  "@pirate-sea-race/simulation/intel",
50	  "@pirate-sea-race/simulation/match",
51	  "@pirate-sea-race/server",
52	  "@pirate-sea-race/server/schema",
53	  "@pirate-sea-race/test-tools",
54	];
55	
56	let server: ChildProcess | undefined;
57	
58	function log(message: string): void {
59	  console.log(`build smoke: ${message}`);
60	}
61	
62	function withTimeout<T>(promise: Promise<T>, timeoutMs: number, what: string): Promise<T> {
63	  let timer: NodeJS.Timeout | undefined;
64	  const timeout = new Promise<never>((_, reject) => {
65	    timer = setTimeout(() => reject(new Error(`${what} did not finish within ${timeoutMs} ms`)), timeoutMs);
66	  });
67	  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
68	}
69	
70	function sleep(ms: number): Promise<void> {
71	  return new Promise((resolve) => setTimeout(resolve, ms));
72	}
73	
74	function running(child: ChildProcess): boolean {
75	  return child.exitCode === null && child.signalCode === null;
76	}
77	
78	async function checkWorkspaceExports(): Promise<void> {
79	  for (const specifier of WORKSPACE_EXPORTS) {
80	    const resolved = fileURLToPath(import.meta.resolve(specifier));
81	    if (!/[\\/]dist[\\/](?:[^\\/]+[\\/])*[^\\/]+\.js$/.test(resolved)) throw new Error(`${specifier} resolves to ${resolved}, not to its dist/`);
82	    const module = (await import(specifier)) as Record<string, unknown>;
83	    if (Object.keys(module).length === 0) throw new Error(`${specifier} (${resolved}) exports nothing`);
84	  }
85	  log(`${WORKSPACE_EXPORTS.length} workspace exports load from dist/`);
86	}
87	
88	/** The production web bundle must not contain the development-only socket delay. */
89	async function checkWebBundle(): Promise<void> {
90	  const directory = new URL(`../${WEB_ASSETS}/`, import.meta.url);
91	  const scripts = (await readdir(directory)).filter((name) => name.endsWith(".js"));
92	  if (scripts.length === 0) throw new Error(`${WEB_ASSETS} holds no scripts`);
93	  for (const name of scripts) {
94	    if ((await readFile(new URL(name, directory), "utf8")).includes(DEV_LATENCY_MARKER)) {
95	      throw new Error(`${WEB_ASSETS}/${name} contains the development-only latency setting`);
96	    }
97	  }
98	  log(`the web bundle (${scripts.length} scripts) carries no development-only latency setting`);
99	}
100	
101	/** Starts the built server on a free port and resolves with the port from its "listening" line. */
102	function startServer(): Promise<number> {
103	  const child = spawn(process.execPath, [SERVER_ENTRY], {
104	    cwd: root,
105	    env: { ...process.env, PORT: "0", PIRATE_SEA_RACE_TEST_PLACEMENT: "1" },
106	    stdio: ["ignore", "pipe", "pipe"],
107	  });
108	  server = child;
109	  child.stderr!.on("data", (chunk: Buffer) => process.stderr.write(chunk));
110	  return withTimeout(
111	    new Promise<number>((resolve, reject) => {
112	      createInterface({ input: child.stdout! }).on("line", (line) => {
113	        console.log(`  server: ${line}`);
114	        const match = LISTENING_LINE.exec(line);
115	        if (match !== null) resolve(Number(match[1]));
116	      });
117	      child.once("error", reject);
118	      child.once("exit", (code, signal) => reject(new Error(`${SERVER_ENTRY} exited (code ${code}, signal ${signal}) before listening`)));
119	    }),
120	    LISTEN_TIMEOUT_MS,
121	    `${SERVER_ENTRY} listening`,
122	  );
123	}
124	
125	async function waitForHealth(endpoint: string): Promise<void> {
126	  const deadline = Date.now() + HEALTH_TIMEOUT_MS;
127	  let last: unknown;
128	  while (Date.now() < deadline) {
129	    try {
130	      const response = await fetch(`${endpoint}/__healthcheck`, { signal: AbortSignal.timeout(1000) });
131	      if (response.ok) return;
132	      last = new Error(`HTTP ${response.status}`);
133	    } catch (error) {
134	      last = error;
135	    }
136	    await sleep(100);
137	  }
138	  throw new Error(`${endpoint}/__healthcheck did not answer OK within ${HEALTH_TIMEOUT_MS} ms`, { cause: last });
139	}
140	
141	async function createMatch(endpoint: string): Promise<void> {
142	  const { HeadlessClient } = await import("@pirate-sea-race/test-tools");
143	  const { TEST_PLACEMENT_PATH } = await import("@pirate-sea-race/protocol");
144	  const host = await withTimeout(HeadlessClient.create(endpoint), MATCH_TIMEOUT_MS, "creating a match");
145	  try {
146	    const ship = host.ship();
147	    if (!/^[A-Z0-9]{6}$/.test(host.code)) throw new Error(`the match has no code (got "${host.code}")`);
148	    if (ship === undefined || host.playerCount !== 1) throw new Error("the creator's ship is not in the match state");
149	    log(`created match ${host.code}; the creator's ship is at (${ship.x}, ${ship.y})`);
150	    // The production entry never reads the test-placement setting, even when the environment sets it.
151	    const response = await fetch(`${endpoint}${TEST_PLACEMENT_PATH}`, {
152	      method: "POST",
153	      headers: { "content-type": "application/json" },
154	      body: JSON.stringify({ code: host.code, sessionId: host.sessionId, tileX: 100, tileY: 76, heading: 0 }),
155	      signal: AbortSignal.timeout(HEALTH_TIMEOUT_MS),
156	    });
157	    if (response.status !== 404) throw new Error(`the production server answered the test placement route with HTTP ${response.status}`);
158	    log("the production server offers no test placement");
159	  } finally {
160	    await withTimeout(host.leave(), STOP_TIMEOUT_MS, "leaving the match").catch(() => undefined);
161	  }
162	}
163	
164	/** A practice duel on the built server: the built rollback core confirms frames and agrees with every server hash. */
165	async function openPracticeDuel(endpoint: string): Promise<void> {
166	  const { HeadlessDuelClient } = await import("@pirate-sea-race/test-tools");
167	  const player = await withTimeout(HeadlessDuelClient.create(endpoint, { practice: true }), MATCH_TIMEOUT_MS, "creating a practice duel");
168	  try {
169	    await withTimeout(player.waitForConfirmed(30, DUEL_TIMEOUT_MS), DUEL_TIMEOUT_MS + 1000, "the practice duel's first frames");
170	    const stats = player.stats!;
171	    if (stats.hashChecks === 0 || stats.desyncs !== 0) throw new Error(`the practice duel's hash checks: ${JSON.stringify(stats)}`);
172	    log(`practice duel ${player.code}: frame ${player.duel!.rollback.confirmedFrame} confirmed, ${stats.hashChecks} hash checks, no desync`);
173	  } finally {
174	    await withTimeout(player.leave(), STOP_TIMEOUT_MS, "leaving the duel").catch(() => undefined);
175	  }
176	}
177	
178	/** Stops the server: SIGTERM lets it drain; SIGKILL follows if it does not exit in time. */
179	async function stopServer(): Promise<void> {
180	  const child = server;
181	  if (child === undefined || !running(child)) return;
182	  const exited = new Promise<void>((resolve) => child.once("exit", () => resolve()));
183	  child.kill("SIGTERM");
184	  await withTimeout(exited, STOP_TIMEOUT_MS, "server shutdown").catch(async () => {
185	    child.kill("SIGKILL");
186	    await withTimeout(exited, STOP_TIMEOUT_MS, "killing the server");
187	  });
188	}
189	
190	// Last resort for paths that skip `finally`: an exit, or a signal from whoever runs the build.
191	process.once("exit", () => {
192	  if (server !== undefined && running(server)) server.kill("SIGKILL");
193	});
194	for (const signal of ["SIGINT", "SIGTERM"] as const) {
195	  process.once(signal, () => {
196	    console.error(`build smoke: interrupted by ${signal}`);
197	    process.exit(1);
198	  });
199	}
200	
201	async function main(): Promise<void> {
202	  await checkWorkspaceExports();
203	  await checkWebBundle();
204	  const port = await startServer();
205	  const endpoint = `http://localhost:${port}`;
206	  log(`${SERVER_ENTRY} listens on port ${port}`);
207	  await waitForHealth(endpoint);
208	  log("health check answers");
209	  await createMatch(endpoint);
210	  await openPracticeDuel(endpoint);
211	}
212	
213	let failed = false;
214	try {
215	  await withTimeout(main(), OVERALL_TIMEOUT_MS, "the build smoke test");
216	  log("passed");
217	} catch (error) {
218	  failed = true;
219	  console.error("build smoke: FAILED");
220	  console.error(error);
221	} finally {
222	  await stopServer().catch((error: unknown) => {
223	    failed = true;
224	    console.error("build smoke: could not stop the server", error);
225	  });
226	}
227	process.exit(failed ? 1 : 0);
228

